  "query": "create extension if not exists pgmq;
create extension if not exists pg_cron with schema pg_catalog;

do $$
begin
  if not exists (
    select 1
    from pgmq.list_queues()
    where queue_name = 'tasks'
  ) then
    perform pgmq.create('tasks');
  end if;
end
$$;

select cron.schedule(
  'enqueue-tasks',
  '* * * * *',
  $$
    select pgmq.send(
      'tasks',
      jsonb_build_object('enqueued_at', clock_timestamp())
    );
  $$
);"
}

