{
  "project_id": "8d628779a2784ed793d6",
  "name": "process-tasks",
  "entrypoint_path": "index.ts",
  "import_map_path": "deno.json",
  "verify_jwt": true,
  "files": [
    {
      "name": "index.ts",
      "content": "import 'jsr:@supabase/functions-js/edge-runtime.d.ts'
import postgres from 'https://deno.land/x/postgresjs@v3.4.5/mod.js'

type QueueMessage = {
  msg_id: string
  message: unknown
}

const queueName = 'tasks'
const batchSize = 100
const visibilityTimeoutSeconds = 60

Deno.serve(async (req) => {
  if (req.method !== 'POST') {
    return new Response('Expected POST', { status: 405 })
  }

  const databaseUrl = Deno.env.get('SUPABASE_DB_URL')
  if (!databaseUrl) {
    return new Response('SUPABASE_DB_URL is not configured', { status: 500 })
  }

  const sql = postgres(databaseUrl, { prepare: false })

  try {
    // Reading sets a visibility timeout. A message is deleted only after its
    // processing succeeds, so an interrupted/failed invocation can retry it.
    const messages = await sql<QueueMessage[]>`
      select msg_id, message
      from pgmq.read(${queueName}, ${visibilityTimeoutSeconds}, ${batchSize})
    `

    for (const message of messages) {
      console.log('Processing task', { msg_id: message.msg_id, message: message.message })
      await sql`select pgmq.delete(${queueName}, ${message.msg_id}::bigint)`
    }

    return Response.json({ processed: messages.length })
  } catch (error) {
    console.error('Failed to process tasks', error)
    return Response.json(
      { error: error instanceof Error ? error.message : 'Unknown error' },
      { status: 500 },
    )
  } finally {
    await sql.end({ timeout: 5 })
  }
})
"
    },
    {
      "name": "deno.json",
      "content": "{
  "compilerOptions": {
    "strict": true
  }
}
"
    }
  ]
}

